<script setup lang="ts">
import { ref,watch } from 'vue';import { X,ImagePlus,Send,Plus } from '@lucide/vue';import { api,http,assetUrl } from '@/api/http';import { useCartStore } from '@/stores/cart';import type { AiConversation,AiResult } from '@/types'
const open=defineModel<boolean>({default:false});const text=ref('鸡胸肉、西兰花，想吃低脂高蛋白'),preferences=ref('2人份，少油少盐，30分钟内'),file=ref<File>(),preview=ref(''),loading=ref(false),conversationId=ref(''),result=ref<AiResult>(),tab=ref<'order'|'cook'>('order');const cart=useCartStore()
watch(open,async value=>{if(value&&!conversationId.value){const c=await api<AiConversation>({url:'/user/ai/conversations',method:'POST'});conversationId.value=c.id}})
function pick(event:Event){const selected=(event.target as HTMLInputElement).files?.[0];if(!selected)return;if(selected.size>5*1024*1024){alert('图片不能超过5MB');return}file.value=selected;preview.value=URL.createObjectURL(selected)}
async function analyze(){if(!text.value.trim()&&!file.value)return;loading.value=true;result.value=undefined;try{if(file.value){const form=new FormData();form.append('conversationId',conversationId.value);form.append('ingredients',text.value);form.append('preferences',preferences.value);form.append('image',file.value);const {data}=await http.post('/user/ai/analyze',form);result.value=data.data}else result.value=await api<AiResult>({url:'/user/ai/analyze/text',method:'POST',data:{conversationId:conversationId.value,ingredients:text.value,preferences:preferences.value}})}catch(e){alert((e as Error).message)}finally{loading.value=false}}
</script>
<template><div v-if="open" class="drawer-mask" @click.self="open=false"><aside class="ai-drawer"><header><div><span>AI PRIVATE CHEF</span><h2>云膳 AI 私厨</h2></div><button @click="open=false"><X/></button></header><div class="ai-scroll"><div class="ai-form"><textarea v-model="text" placeholder="描述食材和今天想吃什么"></textarea><input v-model="preferences" placeholder="人数、口味、忌口、时间"/><img v-if="preview" :src="preview" class="upload-preview"/><div><label><ImagePlus :size="18"/>上传食材<input type="file" accept="image/*" @change="pick"/></label><button @click="analyze" :disabled="loading"><Send :size="17"/>{{loading?'AI分析中…':'开始分析'}}</button></div></div><template v-if="result"><div class="result-tabs"><button :class="{active:tab==='order'}" @click="tab='order'">直接点</button><button :class="{active:tab==='cook'}" @click="tab='cook'">自己做</button></div><div v-if="tab==='order'" class="ai-results"><article v-for="d in result.dishRecommendations"><img v-if="d.image" :src="assetUrl(d.image)"/><div><b>{{d.dishName}} <em>{{d.matchScore}}%</em></b><p>{{d.reason}}</p><footer><strong>¥{{d.price}}</strong><button @click="cart.add(d.dishId)"><Plus :size="16"/>加入购物车</button></footer></div></article></div><div v-else class="recipe-results"><article v-for="r in result.recipes"><header><b>{{r.name}}</b><em>{{r.totalScore}}分</em></header><p>{{r.description}}</p><small>营养 {{r.nutritionScore}} · 易做 {{r.difficultyScore}} · {{r.cookingTime}}</small><ol><li v-for="s in r.steps">{{s}}</li></ol></article></div><p class="safety">{{result.safetyNote}}</p></template></div></aside></div></template>
